import type { ReactNode } from 'react'
import { FaqAccordion, type FaqAccordionItem } from '@/react/components/blocks/FaqAccordion'
import { Button } from '@/react/components/ui/Button'
import { cn } from '@/react/lib/cn'

// The site's FAQ (v3/V3Faq): from 1024 the head on the left (4 of 11 columns, 64px apart, held 32px under the header
// while the questions scroll by) and the questions on the right; one column below, the head centered on phones. The
// head is the section head, a lead in the soft gray 24px under it and a quiet button 32px further. `layout="stack"` is
// the earlier site's (v2/V2Faq): the head centered over a narrow list with its hairline at the foot. The rows are
// FaqAccordion. Place it in a page section; it brings no padding of its own. Answer only with what the product states.
export type FaqItem = FaqAccordionItem

export interface FaqBlockProps {
  items: FaqItem[]
  title?: ReactNode
  /** A line under the title. */
  body?: ReactNode
  /** A quiet button under the title: { label: 'Read the docs', href }. */
  action?: { label: string; href?: string }
  /** Names the heading (`<id>-heading`). */
  id?: string
  /** split (head left, questions right) or stack (head over a narrow list). */
  layout?: 'split' | 'stack'
  /** The question open at first; -1 for none. */
  defaultOpen?: number
  className?: string
}

export function FaqBlock({ items, title = 'Questions.', body, action, id = 'faq', layout = 'split', defaultOpen = 0, className }: FaqBlockProps) {
  const stack = layout === 'stack'
  return (
    <section data-ds="faq-block" aria-labelledby={`${id}-heading`} className={cn('grid grid-cols-[minmax(0,1fr)] text-fg', stack ? 'gap-y-16 lg:gap-y-20' : 'gap-y-12 lg:grid-cols-[minmax(0,4fr)_minmax(0,7fr)] lg:items-start lg:gap-x-16', className)}>
      <header className={cn('flex flex-col', stack ? 'items-center text-center' : 'items-start max-md:items-center max-md:text-center lg:sticky lg:top-[calc(var(--ds-size-header)+var(--ds-space-2xl))]')}>
        <h2 id={`${id}-heading`} className="type-section max-lg:[text-box:trim-start_cap_alphabetic]">{title}</h2>
        {body ? <p className="mt-6 max-w-measure type-body-lg text-pretty text-fg-soft">{body}</p> : null}
        {action ? <Button href={action.href} variant="secondary" className="mt-8 max-md:w-full">{action.label}</Button> : null}
      </header>
      <div className="min-w-0">
        <FaqAccordion items={items} defaultOpen={defaultOpen} edge={stack ? 'bottom' : 'top'} narrow={stack} />
      </div>
    </section>
  )
}

export default FaqBlock

'use client'
import { useId, useLayoutEffect, useRef, useState, type KeyboardEvent } from 'react'
import { faqShift, faqSlotHeight, slideFaqRows, type FaqMove } from '@/lib/faq'
import { cn } from '@/react/lib/cn'

// The site's FAQ rows (ui/FaqAccordion, V3Faq.module.css, V2Faq.module.css): questions in DM Sans 20/28 in the soft
// gray (White when open or under the pointer) under #363636 hairlines, 20px above and below (24 from 768), a 12px plus
// that turns to a minus. One answer is open at a time (the first, unless `defaultOpen` says otherwise); it fades in
// over 320ms, 640px wide at most, and every open slot is as tall as the longest answer, so the rows between the one
// closing and the one opening slide by that height (transform only), and the page scrolls with them when the opened
// row would leave the view. Arrows, Home and End move between questions.
// Reduced motion: no slide or fade.
export interface FaqAccordionItem {
  q: string
  a: string
  /** An anchor for the row. */
  id?: string
}

export interface FaqAccordionProps {
  items: FaqAccordionItem[]
  /** The row open at first; -1 for none. */
  defaultOpen?: number
  /** The hairline above the list (top, the default) or under it (bottom, the pricing page's). */
  edge?: 'top' | 'bottom'
  /** Centered and no wider than the measure plus 80px (the pricing page's list). */
  narrow?: boolean
  className?: string
}

const ROW = 'relative border-t border-edge bg-surface first:border-t-0'

export function FaqAccordion({ items, defaultOpen = 0, edge = 'top', narrow = false, className }: FaqAccordionProps) {
  const closed = items.length
  const [open, setOpen] = useState(defaultOpen < 0 ? closed : defaultOpen)
  const listRef = useRef<HTMLDivElement>(null)
  const move = useRef<FaqMove | null>(null)
  const uid = useId()

  const select = (clicked: number) => {
    const next = clicked === open ? closed : clicked
    const distance = faqSlotHeight(listRef.current)
    move.current = { from: open, to: next, distance, shift: faqShift(listRef.current, open, next, distance, closed) }
    setOpen(next)
  }

  useLayoutEffect(() => {
    const pending = move.current
    move.current = null
    if (listRef.current && pending) slideFaqRows(listRef.current, pending)
  }, [open])

  const onKeyDown = (e: KeyboardEvent<HTMLDivElement>) => {
    const triggers = [...(listRef.current?.querySelectorAll<HTMLButtonElement>('[data-trigger]') ?? [])]
    const at = triggers.indexOf(document.activeElement as HTMLButtonElement)
    if (at < 0) return
    const target = ({ ArrowDown: (at + 1) % triggers.length, ArrowUp: (at - 1 + triggers.length) % triggers.length, Home: 0, End: triggers.length - 1 } as Record<string, number>)[e.key]
    if (target === undefined) return
    e.preventDefault()
    triggers[target].focus()
  }

  const sizers = (skip: number) => items.map((other, j) => (j === skip ? null : <span key={`${j}-${other.q}`} aria-hidden="true" data-text={other.a} className="invisible block type-body text-pretty text-fg-soft [grid-area:1/1] before:content-[attr(data-text)]" />))

  return (
    <div ref={listRef} data-ds="faq-accordion" onKeyDown={onKeyDown} className={cn('ds-faq min-w-0 overflow-y-clip border-edge [overflow-anchor:none]', edge === 'top' ? 'border-t' : 'border-b', narrow && 'mx-auto max-w-[calc(var(--ds-layout-measure)+var(--ds-space-5xl))]', className)}>
      <style href="ds-faq-accordion" precedence="ds">{css}</style>
      {items.map((item, i) => {
        const isOpen = i === open
        return (
          <div key={`${i}-${item.q}`} id={item.id} data-open={isOpen} className={ROW}>
            <h3 className="[font:inherit]">
              <button
                type="button"
                id={`${uid}-q-${i}`}
                data-trigger=""
                aria-expanded={isOpen}
                aria-controls={`${uid}-a-${i}`}
                onClick={() => select(i)}
                className="group/faq -mx-2 flex min-h-control-lg w-[calc(100%+2*var(--ds-space-sm))] cursor-pointer items-start justify-between gap-6 rounded-ds-sm px-2 py-5 text-left text-fg-soft transition-[color] duration-160 ease-out outline-offset-[calc(-1*var(--ds-border-focus))] hover:text-fg active:text-fg aria-expanded:text-fg md:py-6"
              >
                <span className="min-w-0 type-body-lg text-balance">{item.q}</span>
                <span aria-hidden="true" className="ds-faq-icon relative h-7 w-3 flex-none" />
              </button>
            </h3>
            <div data-slot="" className={isOpen ? 'h-auto' : 'h-0'}>
              <div className="grid grid-cols-[minmax(0,var(--ds-layout-measure))] bg-surface pb-6 md:pb-8">
                <div id={`${uid}-a-${i}`} role="region" aria-labelledby={`${uid}-q-${i}`} className="ds-faq-panel [grid-area:1/1]">
                  <p className="block type-body text-pretty text-fg-soft">{item.a}</p>
                </div>
                {sizers(i)}
              </div>
            </div>
          </div>
        )
      })}
      <div data-open={open === closed} aria-hidden="true" className={ROW}>
        <div data-slot="" className={open === closed ? 'h-auto' : 'h-0'}>
          <div className="grid grid-cols-[minmax(0,var(--ds-layout-measure))] bg-surface pb-6 md:pb-8">{sizers(-1)}</div>
        </div>
      </div>
    </div>
  )
}

export default FaqAccordion

const css = `
.ds-faq { --faq-dur: var(--ds-duration-glide); --faq-ease: var(--ds-easing-out); }
.ds-faq-icon { transition: transform var(--ds-duration-press) var(--ds-easing-out); }
.ds-faq-icon::before, .ds-faq-icon::after { content: ""; position: absolute; inset: 0; width: var(--ds-space-md); height: var(--ds-stroke); margin: auto; background: currentColor; }
.ds-faq-icon::after { transform: rotate(90deg); transition: transform var(--ds-duration-glide) var(--ds-easing-out); }
[aria-expanded="true"] > .ds-faq-icon::after { transform: rotate(0deg); }
[aria-expanded="false"]:active > .ds-faq-icon { transform: scale(0.75); }
.ds-faq-panel { visibility: hidden; opacity: 0; transition: opacity var(--ds-duration-glide) var(--ds-easing-out), visibility var(--ds-duration-instant) linear var(--ds-duration-glide); }
[data-open="true"] .ds-faq-panel { visibility: visible; opacity: 1; transition: opacity var(--ds-duration-glide) var(--ds-easing-out); }
@media (prefers-reduced-motion: reduce) {
  .ds-faq-panel, [data-open="true"] .ds-faq-panel, .ds-faq-icon::after { transition: none; }
}
`

// The site's FAQ rows (ui/FaqAccordion): when one answer closes and another opens, every answer slot has the height of
// the longest answer, so the rows between the two move by that height. They are drawn where they were and slid to
// their new place by transform only (added to any slide still running), over --faq-dur on the site's ease-out; when the
// row opened would slide out of view above, the page scrolls with it so it stays in view. Both flavors call it after
// the open row changes. With reduced motion nothing slides (the page just keeps the row in view).
export interface FaqMove { from: number; to: number; distance: number; /** How far the page scrolls up so the opened row stays in view. */ shift?: number }

// What a slide still owes the page's scroll, per list, so a second press during a slide measures from where the rows
// will land.
const owed = new WeakMap<HTMLElement, number>()

/** Opening a row below the open one moves it up by the closing answer's height; when that would take it above the
 * view (the page's scroll padding), the page scrolls back with the rows so the question stays where it was read. */
export function faqShift(list: HTMLElement | null, open: number, next: number, distance: number, closed: number): number {
	if (!list || next <= open || next === closed) return 0
	let rest = list.getBoundingClientRect().top - distance + (owed.get(list) ?? 0) + (list.children[next] as HTMLElement).clientTop
	for (let i = 0; i < next; i++) rest += list.children[i].getBoundingClientRect().height
	const inset = parseFloat(getComputedStyle(document.documentElement).scrollPaddingTop) || 0
	return Math.max(0, Math.round(inset - rest))
}

export function slideFaqRows(list: HTMLElement, move: FaqMove) {
	const shift = move.shift ?? 0
	if (!move.distance) return
	if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
		if (shift) window.scrollBy({ top: -shift, behavior: 'instant' })
		return
	}
	const css = getComputedStyle(list)
	const raw = css.getPropertyValue('--faq-dur').trim()
	const duration = raw.endsWith('ms') ? parseFloat(raw) : parseFloat(raw) * 1000
	const easing = css.getPropertyValue('--faq-ease').trim() || 'ease-out'
	const down = move.to > move.from
	const offset = down ? move.distance : -move.distance
	let clock: Animation | undefined
	for (let i = Math.min(move.from, move.to) + 1; i <= Math.max(move.from, move.to); i++) {
		const a = list.children[i]?.animate([{ transform: `translateY(${offset}px)` }, { transform: 'translateY(0)' }], { duration: duration || 320, easing, composite: 'add' })
		clock ??= a
	}
	if (!clock || !shift) return
	// The scroll follows the slide frame by frame, so the opened question holds still on screen.
	const rows = clock
	let paid = 0
	owed.set(list, (owed.get(list) ?? 0) + shift)
	const tick = () => {
		const running = rows.playState === 'running' && list.isConnected
		const progress = running ? (rows.effect?.getComputedTiming().progress ?? 1) : 1
		const before = window.scrollY
		window.scrollBy({ top: paid - shift * (progress as number), behavior: 'instant' })
		const step = before - window.scrollY
		paid += step
		owed.set(list, (owed.get(list) ?? 0) - step)
		if (running) requestAnimationFrame(tick)
		else owed.set(list, (owed.get(list) ?? 0) - (shift - paid))
	}
	requestAnimationFrame(tick)
}

/** The height every open answer slot has (the open slot's), measured before the change. */
export function faqSlotHeight(list: HTMLElement | null): number {
	return list?.querySelector<HTMLElement>('[data-open="true"] [data-slot]')?.getBoundingClientRect().height ?? 0
}

export const faqExample = [
	{ q: 'What does the Creator plan cost?', a: '$10 for your first month, then $20/month.' },
	{ q: 'How many people can use it?', a: 'Unlimited team seats come with the plan, so everyone who makes or reviews creative can search.' },
	{ q: 'Which networks are in the index?', a: 'Meta, TikTok, Instagram, and YouTube creatives in one index.' },
	{ q: 'How long does it take to add a brand?', a: 'Add any brand or creator in under a minute.' },
]

// Joins class names, skipping falsy ones: cn('a', on && 'b', ['c', undefined]). It does not merge conflicting
// utilities (no tailwind-merge), as Vue's class binding does not: the library's classes are written not to compete,
// and a className from the caller is appended after them, as Vue appends a fallthrough class.
export type ClassValue = string | false | null | undefined | 0 | ClassValue[]

export function cn(...values: ClassValue[]): string {
	const out: string[] = []
	for (const v of values) {
		if (!v) continue
		if (Array.isArray(v)) {
			const s = cn(...v)
			if (s) out.push(s)
		}
		else out.push(v)
	}
	return out.join(' ')
}

